{
  "claims": [
    {
      "text": "AWS G6 ephemeral workers cannot reliably maintain stateful model jobs because their public IP changes on each start, requiring control plane resynchronization, and they are subject to idle reaping which can abruptly terminate jobs.",
      "evidence_refs": ["ev-t3-ip-changes", "ev-t3-idle-reaper"]
    },
    {
      "text": "While the EBS volume persists across stops, the process and GPU memory states do not, which undermines the reliability of stateful computations that depend on in-memory data.",
      "evidence_refs": ["ev-t3-ebs-persists"]
    },
    {
      "text": "The platform's design intentionally treats compute state as ephemeral, aligning with the in-memory registry that does not survive restarts, indicating a systemic preference for stateless operations.",
      "evidence_refs": ["ev-t3-registry-inmemory"]
    }
  ],
  "decision": "reject",
  "risks": [
    "Stateful jobs may fail due to unexpected worker shutdowns caused by the idle reaper, leading to data loss or job corruption.",
    "IP address changes could cause communication failures between the control plane and workers during job execution.",
    "Inconsistent behavior when workers are restarted, particularly under high load where capacity scarcity increases the likelihood of failed restarts."
  ],
  "assumptions": [
    "Stateful model jobs require consistent access to worker memory and network identity throughout their lifecycle.",
    "The system's current architecture does not support durable state management for compute workers.",
    "Workers being stopped and started is a common occurrence due to the idle reaper and capacity constraints."
  ]
}

